{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, a long-chain ester prodrug, has only 15% oral bioavailability in humans, below the 20% threshold; this supports low F for a highly lipophilic ester-containing molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "DINCH, a lipophilic diester, is almost completely bioavailable in humans, but its simple cyclohexane-dicarboxylate structure and lack of a reactive beta-lactone make this high-F evidence poorly transferable to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Chloramphenicol palmitate, a fatty ester prodrug, has high oral bioavailability in children, but it is a hydrolyzable prodrug of a small antibiotic, not a GI-targeted lipase inhibitor, so this high-F evidence is not transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a GI-targeted lipase inhibitor with negligible systemic absorption; the only sub-20% oral F analog (laninamivir octanoate, 15%) and the lack of transferable high-F evidence support a low bioavailability prediction.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for orlistat is included in the provided records.",
    "Most high-F records are structurally distant prodrugs or simple diesters with different absorption mechanisms.",
    "Only one record (C31) provides sub-20% oral F, and it is not the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

